import argparse,subprocess,tempfile,json,hashlib
p=argparse.ArgumentParser()
for key in ['editor-root','dotnet','output']:p.add_argument('--'+key,type=Path,required=True)
a=p.parse_args();pin='48e18f71655d0f0d86144c63239331833501fda2';assert subprocess.check_output(['git','-C',str(a.editor_root),'rev-parse','HEAD'],text=True).strip()==pin
text=(a.editor_root/'StepManiaEditor/ActiveEditorChart.cs').read_text(encoding='utf-8-sig');start=text.index('\tprivate (int maxMarkers, int maxEvents, int maxRateAlteringEvents) GetMaxEventsToDrawPerFrame()');body=text.index('{',start);depth=1;end=body+1
while depth:
 depth+=(text[end]=='{')-(text[end]=='}');end+=1
source=text[start:end].replace('private (int maxMarkers','public (int maxMarkers',1)
adapter='''using System.Text.Json;class PreferencesOptions {public int MaxMarkersToDraw=256,MaxEventsToDraw=2048,MaxRateAlteringEventsToProcessPerFrame=256;}class Preferences {public static Preferences Instance=new();public PreferencesOptions PreferencesOptions=new();}class Counts {public int Value;public int GetCount()=>Value;}class Chart {public int Events,Rates;public Counts GetEvents()=>new(){Value=Events};public Counts GetRateAlteringEvents()=>new(){Value=Rates};}class Editor {public static int Visible,Events,Rates;public static (int,int,int) GetActiveChartCounts()=>(Visible,Events,Rates);}class Active {public Chart Chart=new();METHOD}class Program {static void Main(){var output=new List<object>();foreach(int visible in new[]{0,1,2,7})foreach(int events in new[]{0,1,100})foreach(int budget in new[]{-3,0,2048}){Editor.Visible=visible;Editor.Events=events*Math.Max(visible,1);Editor.Rates=events/2*Math.Max(visible,1);var p=Preferences.Instance.PreferencesOptions;p.MaxMarkersToDraw=budget/8;p.MaxEventsToDraw=budget;p.MaxRateAlteringEventsToProcessPerFrame=budget/8;var chart=new Active{Chart=new(){Events=events,Rates=events/2}};var result=chart.GetMaxEventsToDrawPerFrame();output.Add(new{Visible=visible,Events=events,TotalEvents=Editor.Events,Rates=events/2,TotalRates=Editor.Rates,MaxMarkers=p.MaxMarkersToDraw,MaxEvents=p.MaxEventsToDraw,MaxRates=p.MaxRateAlteringEventsToProcessPerFrame,Markers=result.maxMarkers,DrawEvents=result.maxEvents,DrawRates=result.maxRateAlteringEvents});}Console.Write(JsonSerializer.Serialize(output));}}'''.replace('METHOD',source)
with tempfile.TemporaryDirectory(prefix='render-budget-oracle-') as d:
 t=Path(d);(t/'Program.cs').write_text(adapter);(t/'Oracle.csproj').write_text('<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings></PropertyGroup></Project>');subprocess.run([str(a.dotnet),'build',str(t/'Oracle.csproj'),'-c','Release','--nologo','-v','quiet'],check=True);assembly=t/'bin/Release/net10.0/Oracle.dll';result=json.loads(subprocess.check_output([str(a.dotnet),str(assembly)],text=True));sha=hashlib.sha256(assembly.read_bytes()).hexdigest()
a.output.write_text(json.dumps(result,indent=2)+'\n');a.output.with_suffix('.reference.json').write_text(json.dumps({'EditorCommit':pin,'SourceSha256':hashlib.sha256(source.encode()).hexdigest(),'AdapterSha256':hashlib.sha256(adapter.encode()).hexdigest(),'AssemblySha256':sha,'Scope':'Entire original GetMaxEventsToDrawPerFrame method; visibility changed to public only. CountTree/Editor counts and Options numeric fields explicit adapters. Does not execute event enumeration, rendering or selection.'},indent=2)+'\n');print('Executed',len(result),'source budget cases.')
